#!/usr/bin/env node
'use strict';
const STUCK_IDS = [189,190,191,193,363,365,366,368,373,374,376,378,379,383,384,385,386,387,388,389,390,391,392,393,394,395];
const BATCH_SIZE = 8;
const BATCH_DELAY_MS = 30000;
const ITEM_DELAY_MS = 3000;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function main() {
  await require('./src/config/loadSecrets').loadSecrets();
  const { setVisitTranscriptionStatus } = require('./src/utils/visitSchemaCompat');
  const { runAIPipeline } = require('./src/utils/aiPipeline');
  const pool = require('./src/config/db');
  const batches = [];
  for (let i = 0; i < STUCK_IDS.length; i += BATCH_SIZE) {
    batches.push(STUCK_IDS.slice(i, i + BATCH_SIZE));
  }
  console.log('Total visits:', STUCK_IDS.length, 'Batches:', batches.length);
  let queued = 0;
  for (let b = 0; b < batches.length; b++) {
    const batch = batches[b];
    console.log('=== BATCH', b + 1, '/', batches.length, 'ids:', batch.join(','), '===');
    for (const id of batch) {
      console.log('Re-queue visit', id);
      await setVisitTranscriptionStatus(id, 'idle');
      try {
        await runAIPipeline(id, {
          user: { id: 0, name: 'batch-requeue-day1', role: 'admin' },
          completionMessage: 'Day 1 load test recovery',
        });
        const { rows } = await pool.query('SELECT transcription_status FROM visits WHERE id = $1', [id]);
        console.log('  -> status=' + (rows[0]?.transcription_status || 'unknown'));
        queued++;
      } catch (err) {
        const msg = err.message || String(err);
        if (/429|rate limit/i.test(msg)) {
          console.error('  -> RATE LIMIT, waiting 60s...');
          await sleep(60000);
          try {
            await runAIPipeline(id, {
              user: { id: 0, name: 'batch-requeue-day1', role: 'admin' },
              completionMessage: 'Day 1 load test recovery retry',
            });
            queued++;
            console.log('  -> retry OK');
          } catch (e2) {
            console.error('  -> RETRY FAILED:', e2.message);
          }
        } else {
          console.error('  -> ERROR:', msg);
        }
      }
      await sleep(ITEM_DELAY_MS);
    }
    if (b < batches.length - 1) {
      console.log('Waiting', BATCH_DELAY_MS / 1000, 's before next batch...');
      await sleep(BATCH_DELAY_MS);
    }
  }
  console.log('RE-QUEUE COMPLETE. Queued:', queued, '/', STUCK_IDS.length);
  await pool.end();
}
main().catch((e) => { console.error('FATAL', e); process.exit(1); });
EOFSCRIPT
